INSERT INTO tb_wheel /*ProductDAO.insertWheel*/
       (
             WHEEL_ID
           , WHEEL_NM
           , ADT_DSC
           , SIZE_CNTN
           , DEGN_CNTN
           , EXPS_YN
           , DEL_YN

               , WHEEL_IMG_ID

           , CREAT_DTTM
           , CRTR_ID
           , UPDT_DTTM
           , UPDUSR_ID
       )
VALUES
       (
             (SELECT IFNULL(MAX(WHEEL_ID) + 1, 1) FROM tb_wheel A)
           , #{wheelNm}
           , #{adtDsc}
           , #{sizeCntn}
           , #{degnCntn}
           , #{expsYn}
           , 'N'

               , #{wheelImgId}

           , now()
           , #{crtrId}
           , now()
           , #{crtrId}
        )

mapper.update:
UPDATE tb_wheel /*ProductDAO.updateWheel*/
   SET WHEEL_NM      = #{wheelNm}
     , ADT_DSC       = #{adtDsc}
     , SIZE_CNTN     = #{sizeCntn}
     , DEGN_CNTN     = #{degnCntn}
     , EXPS_YN       = #{expsYn}
     , DEL_YN        = 'N'

         , WHEEL_IMG_ID  = #{wheelImgId}

     , UPDT_DTTM     = now()
     , UPDUSR_ID     = #{crtrId}
 WHERE WHEEL_ID      = #{wheelId}

UPDATE tb_wheel /*ProductDAO.updateWheel*/
   SET DEL_YN        = 'Y'
     , UPDT_DTTM     = now()
     , UPDUSR_ID     = #{crtrId}
 WHERE WHEEL_ID      = #{wheelId}

UPDATE tb_exhst /*ProductDAO.updateExhstDispPri*/
   SET DISP_PRI     = #{dispPri}
     , DEL_YN       = 'N'
     , UPDT_DTTM    = now()
     , UPDUSR_ID    = #{crtrId}
 WHERE EXHST_ID     = #{exhstId}

UPDATE tb_exhst /*ProductDAO.updateExhst*/
   SET EXHST_IMG_ID = #{exhstImgId}
     , UPDT_DTTM    = now()
     , UPDUSR_ID    = #{crtrId}
 WHERE EXHST_ID     = #{exhstId}

UPDATE tb_exhst /*ProductDAO.updateExhstdel*/
   SET DEL_YN = 'Y'
 WHERE EXHST_ID = #{exhstId}

UPDATE tb_crbn /*ProductDAO.updateCrbnDispPri*/
   SET DISP_PRI    = #{dispPri}
     , DEL_YN      = 'N'
     , UPDT_DTTM   = now()
     , UPDUSR_ID   = #{crtrId}
 WHERE CRBN_ID     = #{crbnId}

UPDATE tb_crbn /*ProductDAO.updateCrbn*/
   SET CRBN_IMG_ID = #{crbnImgId}
     , UPDT_DTTM = now()
     , UPDUSR_ID = #{crtrId}
 WHERE CRBN_ID  = #{crbnId}

UPDATE tb_crbn /*ProductDAO.updateCrbndel*/
   SET DEL_YN = 'Y'
 WHERE CRBN_ID = #{crbnId}
